import React, { useState } from 'react';
import { getCyberpunkColors } from '../Analysis/ComplaintTrackingChart';
import { analyzeConversation } from '../../services/api';

const ConversationUpload = ({ onConversationAnalyzed, onUploadStarted }) => {
  const [file, setFile] = useState(null);
  const [text, setText] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [uploadType, setUploadType] = useState('text');
  
  const colors = getCyberpunkColors();
  
  const handleTextChange = (e) => {
    setText(e.target.value);
  };
  
  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    setFile(selectedFile);
  };
  
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    
    if (uploadType === 'text' && !text.trim()) {
      setError('Please enter conversation text');
      return;
    }
    
    if (uploadType === 'file' && !file) {
      setError('Please select a file to upload');
      return;
    }
    
    setLoading(true);
    onUploadStarted();
    
    try {
      let result;
      
      if (uploadType === 'text') {
        result = await analyzeConversation(text);
      } else {
        // File upload logic
        const reader = new FileReader();
        reader.onload = async (e) => {
          try {
            const fileContent = e.target.result;
            result = await analyzeConversation(fileContent);
            onConversationAnalyzed(result);
          } catch (err) {
            console.error('Error processing file:', err);
            setError('Failed to process the file. Please check the format and try again.');
          } finally {
            setLoading(false);
          }
        };
        
        reader.onerror = () => {
          setError('Failed to read the file');
          setLoading(false);
        };
        
        reader.readAsText(file);
        return; // Early return for file upload since we're using the async reader
      }
      
      onConversationAnalyzed(result);
    } catch (err) {
      console.error('Error analyzing conversation:', err);
      setError('Failed to analyze the conversation. Please try again.');
    } finally {
      setLoading(false);
    }
  };
  
  const handleUploadTypeChange = (type) => {
    setUploadType(type);
    setError(null);
  };
  
  return (
    <div className="w-full p-3 rounded-lg border border-green-500" style={{
      background: 'rgba(0, 20, 0, 0.7)',
      boxShadow: `0 0 15px ${colors.neon.darkGreen}`
    }}>
      <div className="mb-4 flex justify-center space-x-4">
        <button
          className={`px-4 py-2 font-mono text-sm border ${uploadType === 'text' ? 'border-green-500' : 'border-gray-700'}`}
          style={{
            backgroundColor: 'black',
            color: uploadType === 'text' ? colors.neon.green : colors.text.secondary,
            boxShadow: uploadType === 'text' ? `0 0 10px ${colors.neon.darkGreen}` : 'none'
          }}
          onClick={() => handleUploadTypeChange('text')}
        >
          TEXT INPUT
        </button>
        <button
          className={`px-4 py-2 font-mono text-sm border ${uploadType === 'file' ? 'border-green-500' : 'border-gray-700'}`}
          style={{
            backgroundColor: 'black',
            color: uploadType === 'file' ? colors.neon.green : colors.text.secondary,
            boxShadow: uploadType === 'file' ? `0 0 10px ${colors.neon.darkGreen}` : 'none'
          }}
          onClick={() => handleUploadTypeChange('file')}
        >
          FILE UPLOAD
        </button>
      </div>
      
      <form onSubmit={handleSubmit}>
        {uploadType === 'text' ? (
          <div className="mb-4">
            <textarea
              className="w-full h-40 p-3 font-mono text-sm bg-black border border-green-500 rounded-lg"
              style={{
                color: colors.neon.green,
                boxShadow: `0 0 10px ${colors.neon.darkGreen}`,
                resize: 'none'
              }}
              placeholder="Enter conversation text here..."
              value={text}
              onChange={handleTextChange}
            />
          </div>
        ) : (
          <div className="mb-4 flex flex-col items-center">
            <div className="w-full p-8 border-2 border-dashed border-green-500 rounded-lg text-center cursor-pointer"
              style={{
                backgroundColor: 'rgba(0, 10, 0, 0.5)',
                color: colors.neon.darkGreen
              }}
              onClick={() => document.getElementById('file-upload').click()}
            >
              <p className="font-mono text-sm mb-2">DRAG FILES HERE OR CLICK TO BROWSE</p>
              <p className="font-mono text-xs">.TXT, .CSV, .JSON supported</p>
              
              {file && (
                <div className="mt-4 p-2 bg-black border border-green-500 inline-block rounded">
                  <span className="font-mono text-xs" style={{color: colors.neon.green}}>
                    {file.name}
                  </span>
                </div>
              )}
            </div>
            <input
              id="file-upload"
              type="file"
              className="hidden"
              accept=".txt,.csv,.json"
              onChange={handleFileChange}
            />
          </div>
        )}
        
        {error && (
          <div className="mb-4 p-2 border border-red-500 rounded-lg bg-black text-center">
            <p className="font-mono text-sm text-red-500">{error}</p>
          </div>
        )}
        
        <div className="flex justify-center">
          <button
            type="submit"
            className="px-6 py-2 bg-black font-mono text-sm font-bold border border-green-500 rounded-lg"
            style={{
              color: colors.neon.green,
              boxShadow: `0 0 15px ${colors.neon.darkGreen}`
            }}
            disabled={loading}
          >
            {loading ? 'PROCESSING...' : 'ANALYZE CONVERSATION'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default ConversationUpload;
